import sys, time
sys.path.insert(0, '/workspace/submission')
import numpy as np
from te.engine.qp import solve_qp

def gen(seed, nmax=96, mmax=24, mixed=True):
    r = np.random.default_rng(seed)
    m = int(r.integers(1, mmax + 1))
    # partition n variables into m nonempty blocks
    n = int(r.integers(m, nmax + 1))
    cuts = sorted(r.choice(np.arange(1, n), size=m - 1, replace=False)) if m > 1 else []
    bounds = [0] + [int(c) for c in cuts] + [n]
    blocks = [list(range(bounds[k], bounds[k + 1])) for k in range(m)]
    C = np.zeros((m, n))
    for k in range(m):
        for i in blocks[k]:
            C[k, i] = 1.0
    route = (not mixed) or bool(r.integers(0, 2))
    eq = [route] * m
    d = np.zeros(m)
    for k in range(m):
        d[k] = float(r.integers(1, 1001)) if (route or r.integers(0, 2)) else 0.0
    E = int(r.integers(1, 65))
    A = np.zeros((E, n))
    for e in range(E):
        for i in range(n):
            if r.random() < 0.3:
                A[e, i] = 1.0 / float(r.integers(1, 1001))
    rho = float(r.integers(1, 9))
    Q = np.eye(n) + rho * A.T @ A
    B = r.normal(0, 50, E)
    q = -rho * A.T @ B - (0.0 if route else 1.0)
    x0 = np.zeros(n)
    if route:
        for k in range(m):
            v = d[k] / len(blocks[k])
            for i in blocks[k]:
                x0[i] = v
    return Q, q, C, d, [bool(e) for e in eq], x0

def check(Q, q, C, d, eq, x, lam):
    n = len(q); m = len(d)
    prob = []
    if x.min() < -1e-9: prob.append('neg x %g' % x.min())
    g = Q @ x + q
    nu = g + C.T @ lam
    for i in range(n):
        if x[i] <= 0 and nu[i] < -1e-7:
            prob.append('nu[%d]=%g' % (i, nu[i]))
    for k in range(m):
        if eq[k]:
            if abs(C[k] @ x - d[k]) > 1e-6 * max(1.0, d[k]):
                prob.append('eq %d resid %g' % (k, C[k] @ x - d[k]))
        else:
            if C[k] @ x > d[k] + 1e-6 * max(1.0, d[k]):
                prob.append('ineq %d viol %g' % (k, C[k] @ x - d[k]))
            if lam[k] < -1e-9:
                prob.append('lam %d %g' % (k, lam[k]))
    for k in range(m):
        if not eq[k] and lam[k] * (d[k] - C[k] @ x) > 1e-5 * max(1.0, abs(d[k])):
            prob.append('comp %d %g' % (k, lam[k] * (d[k] - C[k] @ x)))
    for i in range(n):
        if x[i] * nu[i] < -1e-5 * max(1.0, abs(x[i] * nu[i])):
            prob.append('compx %d %g' % (i, x[i] * nu[i]))
    return prob

t0 = time.time()
fails = 0
N = 400
for seed in range(N):
    Q, q, C, d, eq, x0 = gen(seed)
    x, lam, ok = solve_qp(Q, q, C, d, eq, x0)
    prob = check(Q, q, C, d, eq, x, lam)
    if prob or not ok:
        fails += 1
        if fails < 8:
            print('seed', seed, 'ok', ok, 'n', len(q), 'm', len(d), 'route', all(eq), prob[:4])
print('N', N, 'fails', fails, 'time %.2fs' % (time.time() - t0))
